files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --btn: #3b3f5c;
  --btn-hover: #4e5378;
  --btn-active: #5f6590;
  --correct: #38b764;
  --wrong: #b13e53;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 8px 8px 0 #000;
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 16px;
  color: var(--accent);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.question {
  font-size: 1.4rem;
  margin: 0 0 24px;
  min-height: 2em;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1.1rem;
  padding: 12px 20px;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: var(--btn);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  min-width: 80px;
}

button:hover {
  background: var(--btn-hover);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  background: var(--btn-active);
  transform: translateY(2px);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.answer.correct {
  background: var(--correct);
  border-color: var(--correct);
}

.answer.wrong {
  background: var(--wrong);
  border-color: var(--wrong);
}

.score-line {
  font-size: 1.2rem;
  margin: 0 0 24px;
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.control {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
  font-weight: bold;
}

.control:hover {
  background: #ffe08a;
}

.control:active {
  background: #e6b85c;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  button { font-size: 1rem; padding: 10px 16px; }
  h1 { font-size: 1.3rem; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let score = 0;
let currentQuestion = 1;
let answered = false;

const questions = {
  1: { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  2: { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
};

function renderQuestion(n) {
  const q = questions[n];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  answered = false;
}

function handleAnswer(choice) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  const q = questions[currentQuestion];
  const btn = choice === 'a' ? answerA : answerB;
  if (q.correct === choice) {
    score += 1;
    scoreEl.textContent = score;
    btn.classList.add('correct');
  } else {
    btn.classList.add('wrong');
    const correctBtn = q.correct === 'a' ? answerA : answerB;
    correctBtn.classList.add('correct');
  }
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (currentQuestion === 1) {
    currentQuestion = 2;
    renderQuestion(2);
  } else if (currentQuestion === 2) {
    currentQuestion = 3;
    questionEl.textContent = 'Finished';
    answerA.hidden = true;
    answerB.hidden = true;
  }
});

restartBtn.addEventListener('click', () => {
  score = 0;
  scoreEl.textContent = '0';
  currentQuestion = 1;
  answerA.hidden = false;
  answerB.hidden = false;
  renderQuestion(1);
});

renderQuestion(1);
